#pragma once

#include "common/checkMacros.h"
#include "cudaMacros.h"
#include <NvInferRuntime.h>
#include <algorithm>
#include <array>
#include <cassert>
#include <cstdint>
#include <cuda_bf16.h>
#include <cuda_fp16.h>
