33	{
34	
35	size_t getTypeSize(DataType dataType)
36	{
37	    size_t size{0};
38	    switch (dataType)
39	    {
40	    case DataType::kINT64:
41	    {
42	        size = 8;
43	        break;
44	    }
45	    case DataType::kFLOAT:
46	    case DataType::kINT32:
47	    {
48	        size = 4;
49	        break;
50	    }
51	    case DataType::kHALF:
52	    case DataType::kBF16:
53	    {
54	        size = 2;
55	        break;
56	    }
57	    case DataType::kBOOL:
58	    case DataType::kFP8:
59	    case DataType::kINT8:
60	    case DataType::kUINT8:
61	    {
62	        size = 1;
63	        break;
64	    }
65	    default:
66	    {
67	        // Sub-byte types cannot be processed here.
68	        throw std::runtime_error("Other types are not supported");
69	    }
70	    }
71	    return size;
72	}
73	
74	std::array<int64_t, kMAX_DIMS> computeStrides(Coords const& shape)
75	{
76	    std::array<int64_t, kMAX_DIMS> strides;
77	    int32_t const numDims = shape.getNumDims();
78	    strides[numDims - 1] = 1;
79	    int64_t stride = 1;
80	    for (int32_t i = numDims - 2; i >= 0; --i)
81	    {
82	        stride *= shape[i + 1];
83	        strides[i] = stride;
84	    }
85	    return strides;
86	}
87	} // namespace utils
88	
89	bool Coords::operator==(Coords const& other) const noexcept
90	{
91	    if (mNumDims != other.mNumDims)
92	    {
93	        return false;
94	    }
95	    return std::equal(mDims.begin(), mDims.begin() + mNumDims, other.mDims.begin());
96	}
97	
98	bool Coords::operator!=(Coords const& other) const noexcept
99	{
100	    return !(*this == other);
101	}
102	
103	int64_t Coords::volume() const noexcept
104	{
105	    if (mNumDims == 0)
106	    {
107	        return 0;
108	    }
109	    int64_t vol = 1;
110	    for (int32_t i = 0; i < mNumDims; ++i)
111	    {
112	        vol *= mDims[i];
113	    }
114	    return vol;
115	}
116	
117	nvinfer1::Dims Coords::getTRTDims() const noexcept
118	{
119	    nvinfer1::Dims dims;
120	    dims.nbDims = mNumDims;
121	    for (int32_t i = 0; i < mNumDims; ++i)
122	    {
123	        dims.d[i] = mDims[i];
124	    }
125	    return dims;
126	}
127	
128	std::string Coords::formatString() const
129	{
130	    std::stringstream ss;
131	    ss << "[";
132	    for (int32_t i = 0; i < mNumDims; ++i)
133	    {
134	        ss << mDims[i];
135	        if (i < mNumDims - 1)
136	        {
137	            ss << ", ";
138	        }
139	    }
140	    ss << "]";
141	    return ss.str();
142	}
143	
144	Tensor::Tensor(Coords const& shape, DeviceType deviceType, nvinfer1::DataType dataType, std::string const& name)
145	{
146	    ELLM_CHECK(shape.volume() > 0, "Construction of Tensor object with zero volume is prohibited");
147	#if NV_TENSORRT_MAJOR >= 10 && NV_TENSORRT_MINOR >= 8
148	    if (dataType == DataType::kINT4 || dataType == DataType::kFP4)
149	#else
150	    if (dataType == DataType::kINT4)
151	#endif
152	    {
153	        throw std::runtime_error("Sub-type like kInt4 or kFP4 are not supported");
154	    }
155	
156	    mShape = shape;
157	    mDeviceType = deviceType;
158	    mDataType = dataType;
159	    ownMemory = true;
160	    mStrides = utils::computeStrides(shape);
161	    mName = name;
162	    memoryCapacity = shape.volume() * utils::getTypeSize(dataType);
163	    if (deviceType == DeviceType::kCPU)
164	    {
165	        CUDA_CHECK(cudaMallocHost(&data, memoryCapacity));
166	        LOG_DEBUG("Tensor %s of shape %s with size %ld bytes (%.2f MB) allocated on CPU", name.c_str(),
167	            shape.formatString().c_str(), memoryCapacity, utils::toMB(memoryCapacity));
168	    }
169	    else
170	    {
171	        CUDA_CHECK(cudaMalloc(&data, memoryCapacity));
172	        LOG_DEBUG("Tensor %s of shape %s with size %ld bytes (%.2f MB) allocated on GPU", name.c_str(),
173	            shape.formatString().c_str(), memoryCapacity, utils::toMB(memoryCapacity));
174	    }
175	}
176	
177	Tensor::Tensor(
178	    void* data, Coords const& shape, DeviceType deviceType, nvinfer1::DataType dataType, std::string const& name)
179	{
180	    // Populate the tensor information and only serve as a data container with shape.
181	    mShape = shape;
182	    mDeviceType = deviceType;
183	    mDataType = dataType;
184	    ownMemory = false;
185	
186	    // Allow construction of a non-owned tensor with zero volume.
187	    // The data pointer won't be granted to the tensor object since no access is needed for zero-volume tensors.
188	    if (shape.volume() != 0)
189	    {
190	        mStrides = utils::computeStrides(shape);
191	        this->data = data;
192	        memoryCapacity = shape.volume() * utils::getTypeSize(dataType);
193	    }
194	    else
195	    {
196	        this->data = nullptr;
197	        memoryCapacity = 0;
198	        mStrides = {};
199	    }
200	    mName = name;
201	}
202	
203	Tensor::~Tensor() noexcept
204	{
205	    try
206	    {
207	        releaseResource();
208	    }
209	    catch (std::exception const& e)
210	    {
211	        LOG_ERROR("Exception during tensor destruction: %s", e.what());
212	    }
213	    catch (...)
214	    {
215	    }
216	}
217	
218	Tensor::Tensor(Tensor&& other) noexcept
219	{
220	    this->data = other.data;
221	    this->mShape = other.mShape;
222	    this->mStrides = other.mStrides;
223	    this->mDeviceType = other.mDeviceType;
224	    this->mDataType = other.mDataType;
225	    this->ownMemory = other.ownMemory;
226	    this->memoryCapacity = other.memoryCapacity;
227	    this->mName = other.mName;
228	    // Reset the other tensor.
229	    other.data = nullptr;
230	    other.mShape = Coords{};
231	    other.mStrides = std::array<int64_t, kMAX_DIMS>{};
232	    other.mDeviceType = DeviceType::kCPU;
233	    other.mDataType = DataType::kFLOAT;
234	    other.ownMemory = false;
235	    other.memoryCapacity = 0;
236	    other.mName = {};
237	}
238	
239	Tensor& Tensor::operator=(Tensor&& other) noexcept
240	{
241	    if (this != &other)
242	    {
243	        try
244	        {
245	            releaseResource();
246	        }
247	        catch (...)
248	        {
249	        }
250	        this->data = other.data;
251	        this->mShape = other.mShape;
252	        this->mStrides = other.mStrides;
253	        this->mDeviceType = other.mDeviceType;
254	        this->mDataType = other.mDataType;
255	        this->ownMemory = other.ownMemory;
256	        this->memoryCapacity = other.memoryCapacity;
257	        this->mName = other.mName;
258	        // Reset the other tensor.
259	        other.data = nullptr;
260	        other.mShape = {};
261	        other.mStrides = {};
262	        other.mDeviceType = {};
263	        other.mDataType = {};
264	        other.ownMemory = false;
265	        other.memoryCapacity = 0;
266	        other.mName = {};
267	    }
268	    return *this;
269	}
270	
271	Coords Tensor::getShape() const noexcept
272	{
273	    return mShape;
274	}
275	
276	DeviceType Tensor::getDeviceType() const noexcept
277	{
278	    return mDeviceType;
279	}
280	
281	DataType Tensor::getDataType() const noexcept
282	{
283	    return mDataType;
284	}
285	
286	std::string const& Tensor::getName() const noexcept
287	{
288	    return mName;
289	}
290	
291	bool Tensor::getOwnMemory() const noexcept
292	{
293	    return ownMemory;
294	}
295	
296	int64_t Tensor::getMemoryCapacity() const noexcept
297	{
298	    return memoryCapacity;
299	}
300	
301	int64_t Tensor::getStride(int32_t idx) const
302	{
303	    if (idx < 0 || idx >= mShape.getNumDims())
304	    {
305	        throw std::out_of_range("Tensor: indexing of strides out of range");
306	    }
307	    return mStrides[idx];
308	}
309	
310	Dims Tensor::getTRTDims() const noexcept
311	{
312	    Dims dims;
313	    dims.nbDims = mShape.getNumDims();
314	    for (int32_t i = 0; i < mShape.getNumDims(); ++i)
315	    {
316	        dims.d[i] = mShape[i];
317	    }
318	    return dims;
319	}
320	
321	bool Tensor::isEmpty() const noexcept
322	{
323	    return mShape.volume() == 0;
324	}
325	
326	void* Tensor::rawPointer() noexcept
327	{
328	    return data;
329	}
330	
331	void const* Tensor::rawPointer() const noexcept
332	{
333	    return data;
334	}
335	
336	bool Tensor::reshape(Coords shape) noexcept
337	{
338	    if (!ownMemory)
339	    {
340	        return false;
341	    }
342	
343	    if (static_cast<int64_t>(shape.volume() * utils::getTypeSize(mDataType)) > memoryCapacity)
344	    {
345	        return false;
346	    }
347	
348	    mShape = shape;
349	    mStrides = utils::computeStrides(shape);
350	    return true;
351	}
352	
353	void Tensor::releaseResource()
354	{
355	    if (ownMemory)
356	    {
357	        if (mDeviceType == DeviceType::kCPU)
358	        {
359	            LOG_DEBUG("Tensor %s of shape %s with size %ld bytes (%.2f MB) freed on CPU", mName.c_str(),
360	                mShape.formatString().c_str(), memoryCapacity, utils::toMB(memoryCapacity));
361	            CUDA_CHECK(cudaFreeHost(data));
362	        }
363	        else
364	        {
365	            LOG_DEBUG("Tensor %s of shape %s with size %ld bytes (%.2f MB) freed on GPU", mName.c_str(),
366	                mShape.formatString().c_str(), memoryCapacity, utils::toMB(memoryCapacity));
367	            CUDA_CHECK(cudaFree(data));
368	        }
369	    }
370	    data = nullptr;
371	    ownMemory = false;
372	    memoryCapacity = 0;
373	    mShape = Coords{};
374	    mStrides = std::array<int64_t, kMAX_DIMS>{};
375	    mDeviceType = {};
376	    mDataType = {};
377	    mName = {};
378	}
