87	bool saveSafetensors(std::filesystem::path const& filePath, std::vector<Tensor> const& tensors, cudaStream_t stream)
88	{
89	    if (tensors.empty())
90	    {
91	        LOG_ERROR("Cannot serialize empty tensor vector");
92	        return false;
93	    }
94	
95	    // Create the JSON header
96	    nlohmann::json header;
97	
98	    // Add metadata
99	    header["__metadata__"]
100	        = nlohmann::json::object({{"format", "PT"}, {"version", "1.0"}, {"provider", "tensorrt-edge-llm"}});
101	
102	    // Calculate data offsets and build header
103	    size_t currentOffset = 0;
104	    std::set<std::string> tensorNames;
105	    for (auto const& tensor : tensors)
106	    {
107	        Coords shape = tensor.getShape();
108	        nvinfer1::DataType dataType = tensor.getDataType();
109	        std::string const& name = tensor.getName();
110	
111	        if (name.empty())
112	        {
