119	                "Tensor name %s already exists. Please use a unique name for each tensor for safetensors "
120	                "serialization.",
121	                name.c_str());
122	            return false;
123	        }
124	        tensorNames.insert(name);
125	
126	        // Convert shape to vector<size_t>
127	        std::vector<size_t> shapeVec;
128	        for (int32_t i = 0; i < shape.getNumDims(); ++i)
129	        {
130	            shapeVec.push_back(static_cast<size_t>(shape[i]));
131	        }
132	
133	        // Calculate tensor size using existing getTypeSize function
134	        size_t tensorSize = tensor.getShape().volume() * rt::utils::getTypeSize(dataType);
135	
136	        // Add tensor info to header
137	        header[name] = nlohmann::json::object({{"dtype", dataTypeToString(dataType)}, {"shape", shapeVec},
138	            {"data_offsets", nlohmann::json::array({currentOffset, currentOffset + tensorSize})}});
139	
140	        currentOffset += tensorSize;
141	    }
142	
143	    // Serialize header to string
144	    std::string headerStr = header.dump();
145	
146	    // Calculate header size
147	    uint64_t headerSize = headerStr.size();
148	
149	    // Open file for writing
150	    std::ofstream file(filePath, std::ios::binary);
151	    if (!file.is_open())
152	    {
153	        LOG_ERROR("Failed to open file for writing: %s", filePath.string().c_str());
154	        return false;
155	    }
156	
157	    // Write header size (8 bytes, little-endian)
158	    file.write(reinterpret_cast<char const*>(&headerSize), sizeof(headerSize));
159	
160	    // Write header JSON
161	    file.write(headerStr.c_str(), headerSize);
162	
163	    // Write tensor data
164	    for (auto const& tensor : tensors)
165	    {
166	        void const* data = tensor.rawPointer();
167	        size_t dataSize = tensor.getShape().volume() * rt::utils::getTypeSize(tensor.getDataType());
168	
169	        // If tensor is on GPU, we need to copy to CPU first
170	        if (tensor.getDeviceType() == DeviceType::kGPU)
171	        {
172	            std::vector<uint8_t> cpuData(dataSize);
173	            CUDA_CHECK(cudaMemcpyAsync(cpuData.data(), data, dataSize, cudaMemcpyDeviceToHost, stream));
174	            file.write(reinterpret_cast<char const*>(cpuData.data()), dataSize);
175	        }
176	        else
177	        {
178	            // Tensor is already on CPU
179	            file.write(reinterpret_cast<char const*>(data), dataSize);
