189	bool loadSafetensors(std::filesystem::path const& filePath, std::vector<Tensor>& tensors, cudaStream_t stream)
190	{
191	    tensors.clear();
192	
193	    // Read the file into memory
194	    std::unique_ptr<file_io::MmapReader> mmapReader;
195	    try
196	    {
197	        mmapReader = std::make_unique<file_io::MmapReader>(filePath.string());
198	    }
199	    catch (std::runtime_error const& e)
200	    {
201	        LOG_ERROR("Failed to open file: %s", filePath.string().c_str());
202	        return false;
203	    }
204	
205	    // Read the header size (8 bytes)
206	    uint64_t headerSize = *reinterpret_cast<uint64_t const*>(mmapReader->getByteData());
207	
208	    // Read the metadata JSON
209	    std::string metadataStr(reinterpret_cast<char const*>(mmapReader->getByteData() + sizeof(headerSize)), headerSize);
210	
211	    // Parse the metadata
212	    nlohmann::json header;
213	    try
214	    {
215	        header = nlohmann::json::parse(metadataStr);
216	    }
217	    catch (nlohmann::json::parse_error const& e)
218	    {
219	        LOG_ERROR("Failed to parse JSON metadata: %s", e.what());
220	        return false;
221	    }
222	
223	    // Validate tensor entries and create tensors
224	    size_t tensorDataStart = sizeof(headerSize) + headerSize;
225	
226	    for (auto const& [key, value] : header.items())
227	    {
228	        if (key == "__metadata__")
229	        {
230	            LOG_DEBUG("Loading SafeTensor Header, Metadata: %s", value.dump().c_str());
231	            continue;
232	        }
233	
234	        // Validate tensor entry
235	        if (!value.is_object() || !value.contains("dtype") || !value["dtype"].is_string() || !value.contains("shape")
236	            || !value["shape"].is_array() || !value.contains("data_offsets") || !value["data_offsets"].is_array()
237	            || value["data_offsets"].size() != 2)
238	        {
239	            LOG_ERROR("Malformed tensor entry of SafeTensor object: %s : %s", key.c_str(), value.dump().c_str());
240	            return false;
241	        }
242	
243	        // Extract tensor information
244	        std::string dtype = value["dtype"].get<std::string>();
245	        std::vector<size_t> shapeVec = value["shape"].get<std::vector<size_t>>();
246	        size_t dataStart = value["data_offsets"][0].get<size_t>();
247	        size_t dataEnd = value["data_offsets"][1].get<size_t>();
248	        size_t dataSize = dataEnd - dataStart;
249	
250	        // Convert shape to Coords
251	        std::vector<int64_t> shapeInt64;
252	        for (size_t dim : shapeVec)
253	        {
254	            shapeInt64.push_back(static_cast<int64_t>(dim));
255	        }
256	        Coords shape(shapeInt64);
257	
258	        // Convert dtype to TensorRT data type
259	        nvinfer1::DataType dataType;
260	        try
261	        {
262	            dataType = stringToDataType(dtype);
263	        }
264	        catch (std::runtime_error const& e)
265	        {
266	            LOG_ERROR("Unsupported data type: %s", dtype.c_str());
267	            return false;
268	        }
269	
270	        // Create tensor with owned memory
271	        Tensor tensor(shape, DeviceType::kGPU, dataType, key);
272	
273	        // Copy data from file to GPU
274	        int8_t const* tensorData = mmapReader->getByteData() + tensorDataStart + dataStart;
275	        CUDA_CHECK(cudaMemcpyAsync(tensor.rawPointer(), tensorData, dataSize, cudaMemcpyHostToDevice, stream));
276	
277	        tensors.push_back(std::move(tensor));
278	    }
279	
280	    CUDA_CHECK(cudaStreamSynchronize(stream));
281	
282	    return true;
283	}
